WITH lines AS (SELECT id, effective_from, val FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) t AS val) SELECT id, val, PERCENT_RANK() OVER (ORDER BY val DESC) AS val_percent_rank, RANK() OVER (ORDER BY val NULLS FIRST) AS val_rank, RANK() OVER (ORDER BY val DESC NULLS FIRST) AS val_rank_2, PERCENT_RANK() OVER (ORDER BY val NULLS LAST) AS val_percent_rank_2, RANK() OVER (ORDER BY val DESC NULLS FIRST) AS val_rank_3 FROM lines;
